230	// Resume validation: the resume time must be at least the partition's own
231	// previous watermark and the current effective watermark; equality resumes.
232	func TestAggregateIdleResumeBoundaries(t *testing.T) {
233		cases := []struct {
234			name      string
235			lines     []string
236			resume    string
237			wantError bool
238			wantInMsg string
239		}{
240			{
241				"below own previous",
242				[]string{
243					`{"type":"watermark","time":5000,"partition":0}`,
244					`{"type":"watermark","time":2000,"partition":1}`,
245					`{"type":"idle","partition":1}`, // effective jumps to 5000
246				},
247				`{"type":"watermark","time":1999,"partition":1}`, // < own previous 2000
248				true, "previous watermark",
249			},
250			{
251				"above own previous but below effective",
252				[]string{
253					`{"type":"watermark","time":5000,"partition":0}`,
254					`{"type":"watermark","time":2000,"partition":1}`,
255					`{"type":"idle","partition":1}`, // effective jumps to 5000
256				},
257				`{"type":"watermark","time":3000,"partition":1}`, // >= 2000 own, < 5000 effective
258				true, "effective watermark",
259			},
260			{
261				"equal to own previous and effective",
262				[]string{
263					`{"type":"watermark","time":2000,"partition":0}`,
264					`{"type":"watermark","time":2000,"partition":1}`,
265					`{"type":"idle","partition":1}`, // effective stays 2000
266				},
267				`{"type":"watermark","time":2000,"partition":1}`, // equal to both
268				false, "",
269			},
270			{
271				"equal to advanced effective",
272				[]string{
273					`{"type":"watermark","time":5000,"partition":0}`,
274					`{"type":"watermark","time":2000,"partition":1}`,
275					`{"type":"idle","partition":1}`,
276				},
277				`{"type":"watermark","time":5000,"partition":1}`,
278				false, "",
279			},
280			{
281				"above both",
282				[]string{
283					`{"type":"watermark","time":5000,"partition":0}`,
284					`{"type":"watermark","time":2000,"partition":1}`,
285					`{"type":"idle","partition":1}`,
286				},
287				`{"type":"watermark","time":6000,"partition":1}`,
288				false, "",
289			},
