297				}
298				if !tc.wantError && err != nil {
299					t.Fatalf("unexpected error: %v", err)
300				}
301				if tc.wantError {
302					inputErr, ok := err.(*InputError)
303					if !ok {
304						t.Fatalf("expected *InputError, got %T: %v", err, err)
305					}
306					if inputErr.Line != len(tc.lines)+1 {
307						t.Errorf("line = %d, want %d", inputErr.Line, len(tc.lines)+1)
308					}
309					if !strings.Contains(inputErr.Reason, tc.wantInMsg) {
310						t.Errorf("reason = %q, want substring %q", inputErr.Reason, tc.wantInMsg)
311					}
312				}
313			})
314		}
315	}
316	
317	// A partition that goes idle before ever reporting has no previous watermark:
318	// its resume only has to reach the current effective watermark. The resume
319	// recomputes the effective watermark as the min and never re-emits windows
320	// already closed while the partition was idle.
321	func TestAggregateIdleNeverReportedResume(t *testing.T) {
322		input := strings.Join([]string{
323			`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
324			`{"type":"event","key":"k","time":1100,"value":3,"partition":0}`,
325			`{"type":"idle","partition":1}`,                  // p1 never reported; effective still unknown
326			`{"type":"watermark","time":9000,"partition":0}`, // active set {p0}: closes both windows
327			`{"type":"watermark","time":9000,"partition":1}`, // resume never-reported p1: min = 9000
328		}, "\n")
329		stdout, _, err := runPartitioned(t, input, 1000, 2)
330		if err != nil {
331			t.Fatalf("unexpected error: %v", err)
332		}
333		want := strings.Join([]string{
334			`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
335			`{"key":"k","start":1000,"end":2000,"count":1,"sum":3}`,
336			``,
337		}, "\n")
338		if stdout != want {
339			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
340		}
341	
342		// Even without a previous watermark of its own, resuming below the
343		// current effective watermark fails.
344		below := strings.Join([]string{
345			`{"type":"idle","partition":1}`,
346			`{"type":"watermark","time":9000,"partition":0}`, // effective 9000 while p1 idle
347			`{"type":"watermark","time":8999,"partition":1}`, // resume below effective: line 3 fatal
348		}, "\n")
349		_, _, err = runPartitioned(t, below, 1000, 2)
350		if err == nil {
351			t.Fatal("expected resume below effective watermark to fail")
352		}
353		inputErr := err.(*InputError)
354		if inputErr.Line != 3 {
355			t.Errorf("line = %d, want 3", inputErr.Line)
356		}
357		if !strings.Contains(inputErr.Reason, "effective watermark") {
358			t.Errorf("reason = %q, want effective watermark bound", inputErr.Reason)
359		}
360	}
361	
362	// A resumed partition participates again: its lower watermark pulls the
363	// effective watermark back down to the min, and a regression afterwards is
364	// still fatal.
365	func TestAggregateIdleResumeRejoinsMinimum(t *testing.T) {
366		input := strings.Join([]string{
367			`{"type":"event","key":"k","time":100,"value":1,"partition":0}`,
368			`{"type":"watermark","time":5000,"partition":0}`,
369			`{"type":"idle","partition":1}`,                  // effective = 5000, [0,1000) closes
370			`{"type":"watermark","time":5000,"partition":1}`, // resume: min = 5000
371			`{"type":"watermark","time":6000,"partition":0}`, // min stays 5000
372			`{"type":"watermark","time":4999,"partition":1}`, // regression: fatal line 6
373		}, "\n")
374		stdout, _, err := runPartitioned(t, input, 1000, 2)
