376			t.Fatal("expected watermark regression error after resume")
377		}
378		inputErr := err.(*InputError)
379		if inputErr.Line != 6 {
380			t.Errorf("line = %d, want 6", inputErr.Line)
381		}
382		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":1}` + "\n"
383		if stdout != want {
384			t.Fatalf("stdout = %q, want %q", stdout, want)
385		}
386	}
387	
388	// idle uses the same integer partition requirements as other records:
389	// missing, mistyped and out-of-range partitions are fatal with line numbers.
390	func TestAggregateIdlePartitionFieldErrors(t *testing.T) {
391		cases := []struct {
392			name      string
