3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// Regression safeguards for the ordering between record content validation
10	// and the idle-partition resume judgement in partitioned sliding mode. The
11	// history is slidingIdleResumeFixtureLines (window 1000, slide 600, two
12	// partitions, key "sensor-a"): partition 0's event at 700/2 lands in
13	// [0,1000) and [600,1600), partition 1's event at 1000/3 lands only in
14	// [600,1600); after watermarks 2000 on partition 0 and 1000 on partition 1,
15	// [0,1000) is already closed (count 1, sum 2) while [600,1600) stays open.
16	// Partition 0 then declares idle on physical line 6: the effective
17	// watermark stays 1000 (partition 1 is active there), but partition 0's own
18	// old watermark remains 2000.
19	//
20	// The next watermark record (physical line 8) is the partition's resume
21	// record, and the ordering under protection is:
22	//
23	//  1. The "time" field must first parse as a non-negative signed 64-bit
24	//     integer -- missing, string-typed, negative or out-of-range is the
25	//     record's first error even when the same record's "partition" field is
26	//     also wrong, regardless of the two fields' textual order in the JSON.
27	//  2. Only after time is legal may "partition" be read and range-checked;
28	//     a missing, string-typed or out-of-range partition is the reported
29	//     problem even when that legal time (1600) is below the partition's own
30	//     old watermark 2000.
31	//  3. Only with both fields legal do the resume bounds apply, in their
32	//     existing order: the partition's own previous watermark first (so 1600
33	//     fails against 2000) and never the effective watermark 1000.
34	//
35	// Every failure is the existing *InputError naming physical line 8 (blank
36	// physical lines 5 and 7 count) with a distinguishable reason. It must not
37	// become a late-event notice, the window already emitted stays exactly as
38	// published, and the dead records after it (a watermark that would close
39	// [600,1600), then an event that would log a late notice) take no effect.
40	
41	// slidingIdleResumeDeadSuffix are the records that must stay completely dead
42	// after a fatal resume-record error on physical line 8:
43	//
44	//	line 9: partition 1 watermark 1600 -- would close [600,1600) if reached
45	//	line 10: partition 1 event time=999 -- would log a late notice if reached
46	func slidingIdleResumeDeadSuffix() []string {
47		return []string{
48			`{"type":"watermark","time":1600,"partition":1}`,
49			`{"type":"event","key":"sensor-a","time":999,"value":1,"partition":1}`,
50		}
51	}
52	
53	var slidingIdleResumeWantFirstWindow = `{"key":"sensor-a","start":0,"end":1000,"count":1,"sum":2}` + "\n"
54	
55	// assertResumeFieldError checks the common contract of every malformed resume
56	// record: an *InputError (never an *OutputError) on physical line 8, a reason
57	// naming wantField and stating wantCause, with no trace of the other field,
58	// the resume-bound comparisons, a late-event skip or window accumulation;
59	// stderr stays empty and stdout keeps only the window closed before line 8.
60	func assertResumeFieldError(t *testing.T, stdout, stderr string, err error, wantField, wantCause string) {
61		t.Helper()
62		if err == nil {
63			t.Fatalf("a malformed resume record must fail fatally; got nil, stdout=%q stderr=%q", stdout, stderr)
64		}
65		var inputErr *InputError
66		if !errors.As(err, &inputErr) {
67			t.Fatalf("want *InputError, got %T: %v", err, err)
68		}
69		var outputErr *OutputError
70		if errors.As(err, &outputErr) {
71			t.Fatalf("a malformed record must not be reported as an output failure: %v", err)
72		}
73		if inputErr.Line != 8 {
74			t.Errorf("InputError.Line = %d, want 8 (blank physical lines 5 and 7 count)", inputErr.Line)
75		}
76		if !strings.Contains(inputErr.Reason, wantField) {
77			t.Errorf("reason %q must name field %s", inputErr.Reason, wantField)
78		}
79		if !strings.Contains(inputErr.Reason, wantCause) {
80			t.Errorf("reason %q must state the concrete cause %q", inputErr.Reason, wantCause)
81		}
82		// Field validation happens before any idle-resume state is consulted:
83		// neither resume bound may appear in the reason.
84		for _, sub := range []string{"resume watermark", "previous watermark", "effective watermark"} {
85			if strings.Contains(inputErr.Reason, sub) {
86				t.Errorf("a field error must be reported before the resume bounds, reason %q mentions %q", inputErr.Reason, sub)
87			}
88		}
89		if strings.Contains(err.Error(), "late event") {
90			t.Errorf("an invalid resume record must not be described as a late-event skip: %q", err.Error())
91		}
92		if stderr != "" {
93			t.Errorf("a rejected resume record and its dead suffix must write no late-event notice, got %q", stderr)
94		}
95		if stdout != slidingIdleResumeWantFirstWindow {
96			t.Errorf("window output mismatch:\n got: %q\nwant: %q", stdout, slidingIdleResumeWantFirstWindow)
97		}
98	}
99	
100	// TestSlidingIdleResumeInvalidTimeFailsBeforePartition covers every invalid
101	// time shape on a resume record. Each record also carries an invalid
102	// partition (out of range or string-typed) to prove the time field is
103	// settled first: missing time, a string time, a negative time and times
104	// beyond either end of signed 64-bit range are each the concrete first
105	// error on physical line 8.
106	func TestSlidingIdleResumeInvalidTimeFailsBeforePartition(t *testing.T) {
107		cases := []struct {
108			name      string
109			record    string
110			wantField string
111			wantCause string
112		}{
113			{
114				name:      "time missing while partition is out of range",
115				record:    `{"type":"watermark","partition":9}`,
116				wantField: `"time"`,
117				wantCause: `missing required integer field "time"`,
118			},
119			{
120				name:      "time written as string while partition is also a string",
121				record:    `{"type":"watermark","time":"1600","partition":"0"}`,
122				wantField: `"time"`,
123				wantCause: `field "time" must be a signed 64-bit integer, got "1600"`,
124			},
125			{
126				name:      "time negative while partition is out of range",
127				record:    `{"type":"watermark","time":-1,"partition":9}`,
128				wantField: `"time"`,
129				wantCause: `field "time" must be a non-negative integer, got -1`,
130			},
131			{
132				name:      "time above signed 64-bit range while partition is out of range",
133				record:    `{"type":"watermark","time":9223372036854775808,"partition":9}`,
134				wantField: `"time"`,
135				wantCause: `field "time" integer out of signed 64-bit range: 9223372036854775808`,
136			},
137			{
138				name:      "time below signed 64-bit range while partition is out of range",
139				record:    `{"type":"watermark","time":-9223372036854775809,"partition":9}`,
140				wantField: `"time"`,
141				wantCause: `field "time" integer out of signed 64-bit range: -9223372036854775809`,
142			},
143		}
144		for _, tc := range cases {
145			t.Run(tc.name, func(t *testing.T) {
146				lines := append(slidingIdleResumeFixtureLines(), tc.record)
147				lines = append(lines, slidingIdleResumeDeadSuffix()...)
148				stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
149				assertResumeFieldError(t, stdout, stderr, err, tc.wantField, tc.wantCause)
150				// The other field is broken too; it must not be the named one.
151				if inputErr := inputErrorFrom(t, err); strings.Contains(inputErr.Reason, `"partition"`) {
152					t.Errorf("time must be checked before partition, reason = %q", inputErr.Reason)
153				}
154			})
155		}
156	}
157	
158	// TestSlidingIdleResumeFieldOrderDoesNotChangeFirstError proves the first
159	// error is fixed by validation order (time, then partition, then resume
160	// bounds), not by the order the two fields happen to be written in the JSON.
161	// Swapping the textual order must yield the identical physical line and
162	// reason, both when time is the broken field and when a legal-but-low time
163	// accompanies a broken partition.
164	func TestSlidingIdleResumeFieldOrderDoesNotChangeFirstError(t *testing.T) {
165		cases := []struct {
166			name      string
167			timeFirst string
168			partFirst string
169			wantField string
170			wantCause string
171		}{
172			{
173				name:      "string time and string partition",
174				timeFirst: `{"type":"watermark","time":"1600","partition":"0"}`,
175				partFirst: `{"type":"watermark","partition":"0","time":"1600"}`,
176				wantField: `"time"`,
177				wantCause: `field "time" must be a signed 64-bit integer, got "1600"`,
178			},
179			{
180				name:      "negative out-of-range time and out-of-range partition",
181				timeFirst: `{"type":"watermark","time":-1,"partition":9}`,
182				partFirst: `{"type":"watermark","partition":9,"time":-1}`,
183				wantField: `"time"`,
184				wantCause: `field "time" must be a non-negative integer, got -1`,
185			},
186			{
187				name:      "legal low time with string partition",
188				timeFirst: `{"type":"watermark","time":1600,"partition":"0"}`,
189				partFirst: `{"type":"watermark","partition":"0","time":1600}`,
190				wantField: `"partition"`,
191				wantCause: `field "partition" must be a signed 64-bit integer, got "0"`,
192			},
193			{
194				name:      "legal low time with out-of-range partition",
195				timeFirst: `{"type":"watermark","time":1600,"partition":9}`,
196				partFirst: `{"type":"watermark","partition":9,"time":1600}`,
197				wantField: `"partition"`,
198				wantCause: `field "partition" must be an integer in range [0,2), got 9`,
199			},
200		}
201		for _, tc := range cases {
202			t.Run(tc.name, func(t *testing.T) {
203				first := runResumeFieldError(t, tc.timeFirst)
204				second := runResumeFieldError(t, tc.partFirst)
205				if first.Line != 8 || second.Line != 8 {
206					t.Errorf("line numbers = %d and %d, want 8 for both field orders", first.Line, second.Line)
207				}
208				if first.Reason != second.Reason {
209					t.Errorf("field order changed the first error:\n time-first: %q\npart-first: %q", first.Reason, second.Reason)
210				}
211				if !strings.Contains(first.Reason, tc.wantField) {
212					t.Errorf("reason %q must name %s", first.Reason, tc.wantField)
213				}
214				if !strings.Contains(first.Reason, tc.wantCause) {
215					t.Errorf("reason %q must state %q", first.Reason, tc.wantCause)
216				}
217			})
218		}
219	}
220	
221	// TestSlidingIdleResumeInvalidPartitionAfterLegalTime covers the second
222	// stage: once time parses legally, partition problems are reported even
223	// though the time 1600 is below partition 0's own old watermark 2000. The
224	// resume-bound comparison must not run first and "rescue" the record into a
225	// resume-watermark error.
226	func TestSlidingIdleResumeInvalidPartitionAfterLegalTime(t *testing.T) {
227		cases := []struct {
228			name      string
229			record    string
230			wantCause string
231		}{
232			{
233				name:      "partition missing",
234				record:    `{"type":"watermark","time":1600}`,
235				wantCause: `missing required integer field "partition"`,
236			},
237			{
238				name:      "partition written as string",
239				record:    `{"type":"watermark","time":1600,"partition":"0"}`,
240				wantCause: `field "partition" must be a signed 64-bit integer, got "0"`,
241			},
242			{
243				name:      "partition above configured range",
244				record:    `{"type":"watermark","time":1600,"partition":9}`,
245				wantCause: `field "partition" must be an integer in range [0,2), got 9`,
246			},
247			{
248				name:      "partition negative",
249				record:    `{"type":"watermark","time":1600,"partition":-1}`,
250				wantCause: `field "partition" must be an integer in range [0,2), got -1`,
251			},
252		}
253		for _, tc := range cases {
254			t.Run(tc.name, func(t *testing.T) {
255				lines := append(slidingIdleResumeFixtureLines(), tc.record)
256				lines = append(lines, slidingIdleResumeDeadSuffix()...)
257				stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
258				assertResumeFieldError(t, stdout, stderr, err, `"partition"`, tc.wantCause)
259				if inputErr := inputErrorFrom(t, err); strings.Contains(inputErr.Reason, `"time"`) {
260					t.Errorf("time 1600 is legal and must not be blamed: %q", inputErr.Reason)
261				}
262			})
263		}
264	}
265	
266	// TestSlidingIdleResumeLegalFieldsFailsAgainstOwnOldWatermark is the third
267	// stage: with both fields legal the resume bounds apply, and the partition's
268	// own previous watermark (2000) is the one violated by time 1600 -- not the
269	// effective watermark 1000, which 1600 already clears. This is checked with
270	// both JSON field orders; the dead suffix must neither close [600,1600) nor
271	// produce a late-event notice.
272	func TestSlidingIdleResumeLegalFieldsFailsAgainstOwnOldWatermark(t *testing.T) {
273		for _, record := range []string{
274			`{"type":"watermark","time":1600,"partition":0}`,
275			`{"type":"watermark","partition":0,"time":1600}`,
276		} {
277			lines := append(slidingIdleResumeFixtureLines(), record)
278			lines = append(lines, slidingIdleResumeDeadSuffix()...)
279			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
280			if err == nil {
281				t.Fatalf("resume at 1600 must fail against partition 0's old watermark 2000; got nil, stdout=%q", stdout)
282			}
283			var inputErr *InputError
284			if !errors.As(err, &inputErr) {
285				t.Fatalf("want *InputError, got %T: %v", err, err)
286			}
287			if inputErr.Line != 8 {
288				t.Errorf("InputError.Line = %d, want 8", inputErr.Line)
289			}
290			for _, sub := range []string{
291				"resume watermark 1600",
292				"partition 0",
293				"previous watermark 2000",
294			} {
295				if !strings.Contains(inputErr.Reason, sub) {
296					t.Errorf("reason %q must contain %q", inputErr.Reason, sub)
297				}
298			}
299			if strings.Contains(inputErr.Reason, "effective watermark 1000") {
300				t.Errorf("the violated bound must be the partition's own old watermark, not the effective 1000: %q", inputErr.Reason)
301			}
302			if stderr != "" {
303				t.Errorf("no late-event notice may be written, got %q", stderr)
304			}
305			if stdout != slidingIdleResumeWantFirstWindow {
306				t.Errorf("the closed window stays and [600,1600) must not be flushed by the dead suffix:\n got: %q\nwant: %q", stdout, slidingIdleResumeWantFirstWindow)
307			}
308		}
309	}
310	
311	// TestSlidingIdleResumeAtOldWatermarkWaitsForOtherPartition pins the legal
312	// boundary: resuming partition 0 exactly at its own old watermark 2000
313	// succeeds while partition 1 still pins the effective watermark at 1000, so
314	// the resume itself emits nothing -- [600,1600) must not close early and the
315	// already closed [0,1000) must not be re-emitted. The window closes only
316	// once partition 1 advances to 1600, merging the two pre-idle events
317	// (count 2, sum 5, no partition field); a later fast-partition watermark
318	// must not re-emit closed windows or flush still-open ones.
